import { useState, useEffect, useRef } from 'react';
import Head from 'next/head';
import { 
  Activity, AlertTriangle, ShieldCheck, Cpu, Box, 
  Search, MessageSquare, CheckCircle, Clock, Zap,
  Menu, Bell, User, LayoutDashboard, Database, Settings, ShieldAlert
} from 'lucide-react';
import events from '../data/events.json';

import Sidebar from '../components/Sidebar';
import Navbar from '../components/Navbar';

// --- MAIN PAGE ---

export default function Dashboard() {
  const [selectedEvent, setSelectedEvent] = useState(events[0].text);
  const [stage, setStage] = useState(0); 
  const [detectResult, setDetectResult] = useState(null);
  const [impactResult, setImpactResult] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [negotiateResult, setNegotiateResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [chatRevealIndex, setChatRevealIndex] = useState(-1);
  const [approved, setApproved] = useState(false);

  const chatEndRef = useRef(null);

  // Auto-scroll chat
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [chatRevealIndex, negotiateResult]);

  const simulatePipeline = async () => {
    setLoading(true);
    setStage(1);
    
    // 1. Detect
    const r1 = await fetch('/api/detect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ eventText: selectedEvent })
    });
    const d1 = await r1.json();
    setDetectResult(d1);
    
    await new Promise(r => setTimeout(r, 1000));
    setStage(2);
    
    // 2. Impact
    const r2 = await fetch('/api/impact', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ partNumber: d1.partNumber })
    });
    const d2 = await r2.json();
    setImpactResult(d2);

    await new Promise(r => setTimeout(r, 1200));
    setStage(3);

    // 3. Match
    const r3 = await fetch('/api/match', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ partNumber: d1.partNumber })
    });
    const d3 = await r3.json();
    setMatchResult(d3);

    await new Promise(r => setTimeout(r, 1500));
    setStage(4);

    // 4. Negotiate
    const r4 = await fetch('/api/negotiate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ partNumber: d1.partNumber, options: d3 })
    });
    const d4 = await r4.json();
    setNegotiateResult(d4);
    
    setLoading(false);
    
    let index = 0;
    setChatRevealIndex(0);
    const interval = setInterval(() => {
      index++;
      setChatRevealIndex(index);
      if (index >= d4.chatLog.length) {
        clearInterval(interval);
        setTimeout(() => setStage(5), 1500);
      }
    }, 1200); 
  };

  const getStageStatus = (currentStage, targetStage) => {
    if (currentStage > targetStage) return 'COMPLETED';
    if (currentStage === targetStage) return loading ? 'PROCESSING' : 'ACTIVE';
    return 'PENDING';
  };

  return (
    <div className="min-h-screen bg-[#0f1115] flex">
      <Head>
        <title>SentinelChain | Supply Chain Command Center</title>
      </Head>

      <Sidebar />

      <main className="flex-1 lg:ml-64 flex flex-col min-h-screen relative">
        <Navbar />

        <div className="p-6 max-w-6xl mx-auto w-full space-y-6 pb-24">
          
          {/* HEADER */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8">
            <div>
              <h1 className="text-3xl font-bold text-white tracking-tight">Supply Chain Command Center</h1>
              <p className="text-gray-400 mt-1">Monitor disruptions. Quantify impact. Recover faster.</p>
            </div>
            <div className="flex flex-col gap-2 items-end">
              <div className="flex items-center gap-2 text-sm">
                <span className="text-gray-500">Scenario:</span>
                <select 
                  className="bg-transparent border border-white/20 text-white text-sm rounded px-2 py-1 outline-none focus:border-indigo-500 transition-colors"
                  value={selectedEvent}
                  onChange={(e) => setSelectedEvent(e.target.value)}
                  disabled={loading || stage > 0}
                >
                  {events.map((evt) => (
                    <option key={evt.id} value={evt.text} className="bg-gray-900">{evt.text}</option>
                  ))}
                </select>
              </div>
              <div className="flex gap-3">
                {(loading || stage > 0) && (
                  <button 
                    onClick={() => { setStage(0); setDetectResult(null); setImpactResult(null); setMatchResult(null); setNegotiateResult(null); setApproved(false); }}
                    className="px-4 py-2 text-sm font-medium text-gray-300 hover:text-white bg-white/5 hover:bg-white/10 rounded-lg transition-colors border border-white/10"
                  >
                    Reset System
                  </button>
                )}
                <button 
                  onClick={simulatePipeline}
                  disabled={loading || stage > 0}
                  className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-5 py-2 rounded-lg font-medium transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_15px_rgba(79,70,229,0.3)]"
                >
                  <Zap className="w-4 h-4" /> Simulate Disruption
                </button>
              </div>
            </div>
          </div>

          {/* CRITICAL DISRUPTION ALERT */}
          {stage > 0 && detectResult && (
            <div className="glass-panel-danger p-6 animate-[fadeIn_0.3s_ease-out]">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-red-500/20 flex items-center justify-center text-red-500">
                    <AlertTriangle className="w-5 h-5" />
                  </div>
                  <div>
                    <h2 className="text-xl font-bold text-white flex items-center gap-3">
                      CRITICAL DISRUPTION
                      <span className="text-[10px] uppercase tracking-widest bg-red-500/20 text-red-400 px-2 py-0.5 rounded border border-red-500/30">High Severity</span>
                    </h2>
                    <p className="text-red-200 mt-1">{detectResult.reason}</p>
                  </div>
                </div>
                <div className="text-right hidden sm:block">
                  <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Affected Component</p>
                  <p className="font-mono text-lg text-white">{detectResult.partNumber}</p>
                </div>
              </div>
            </div>
          )}

          {/* 4-STAGE PIPELINE VISUAL */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {/* Stage 1 */}
            <div className={`glass-panel p-5 relative overflow-hidden transition-all duration-500 ${stage === 1 ? 'border-indigo-500/50 shadow-[0_0_20px_rgba(79,70,229,0.15)]' : ''}`}>
              {stage === 1 && loading && <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500/20"><div className="h-full bg-indigo-500 animate-[progress_1.5s_ease-in-out_infinite]"></div></div>}
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-mono text-gray-500">01</span>
                <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${getStageStatus(stage, 1) === 'COMPLETED' ? 'bg-emerald-500/20 text-emerald-400' : getStageStatus(stage, 1) === 'PROCESSING' ? 'bg-indigo-500/20 text-indigo-400' : 'bg-gray-800 text-gray-500'}`}>
                  {getStageStatus(stage, 1)}
                </span>
              </div>
              <div className="flex items-center gap-2 mb-1">
                <Search className={`w-4 h-4 ${stage >= 1 ? 'text-indigo-400' : 'text-gray-600'}`} />
                <h3 className={`font-semibold ${stage >= 1 ? 'text-white' : 'text-gray-500'}`}>Detection Agent</h3>
              </div>
              {getStageStatus(stage, 1) === 'PROCESSING' && <p className="text-sm text-gray-400 italic">Analyzing disruption...</p>}
              {getStageStatus(stage, 1) === 'COMPLETED' && detectResult && (
                <div className="mt-3 pt-3 border-t border-white/5">
                  <p className="text-xs text-gray-400">Identified component</p>
                  <p className="text-sm font-mono text-indigo-300 mt-1">→ {detectResult.partNumber}</p>
                </div>
              )}
            </div>

            {/* Stage 2 */}
            <div className={`glass-panel p-5 relative overflow-hidden transition-all duration-500 ${stage === 2 ? 'border-indigo-500/50 shadow-[0_0_20px_rgba(79,70,229,0.15)]' : ''} ${stage < 2 ? 'opacity-50' : ''}`}>
              {stage === 2 && loading && <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500/20"><div className="h-full bg-indigo-500 animate-[progress_1.5s_ease-in-out_infinite]"></div></div>}
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-mono text-gray-500">02</span>
                <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${getStageStatus(stage, 2) === 'COMPLETED' ? 'bg-emerald-500/20 text-emerald-400' : getStageStatus(stage, 2) === 'PROCESSING' ? 'bg-indigo-500/20 text-indigo-400' : 'bg-gray-800 text-gray-500'}`}>
                  {getStageStatus(stage, 2)}
                </span>
              </div>
              <div className="flex items-center gap-2 mb-1">
                <Activity className={`w-4 h-4 ${stage >= 2 ? 'text-orange-400' : 'text-gray-600'}`} />
                <h3 className={`font-semibold ${stage >= 2 ? 'text-white' : 'text-gray-500'}`}>Impact Agent</h3>
              </div>
              {getStageStatus(stage, 2) === 'PROCESSING' && <p className="text-sm text-gray-400 italic">Calculating exposure...</p>}
              {getStageStatus(stage, 2) === 'COMPLETED' && impactResult && (
                <div className="mt-3 pt-3 border-t border-white/5">
                  <p className="text-xs text-gray-400">Revenue exposure</p>
                  <p className="text-sm text-orange-300 mt-1 font-semibold">→ ${impactResult.revenueAtRiskPerDay.toLocaleString()}/day</p>
                </div>
              )}
            </div>

            {/* Stage 3 */}
            <div className={`glass-panel p-5 relative overflow-hidden transition-all duration-500 ${stage === 3 ? 'border-indigo-500/50 shadow-[0_0_20px_rgba(79,70,229,0.15)]' : ''} ${stage < 3 ? 'opacity-50' : ''}`}>
              {stage === 3 && loading && <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500/20"><div className="h-full bg-indigo-500 animate-[progress_1.5s_ease-in-out_infinite]"></div></div>}
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-mono text-gray-500">03</span>
                <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${getStageStatus(stage, 3) === 'COMPLETED' ? 'bg-emerald-500/20 text-emerald-400' : getStageStatus(stage, 3) === 'PROCESSING' ? 'bg-indigo-500/20 text-indigo-400' : 'bg-gray-800 text-gray-500'}`}>
                  {getStageStatus(stage, 3)}
                </span>
              </div>
              <div className="flex items-center gap-2 mb-1">
                <Box className={`w-4 h-4 ${stage >= 3 ? 'text-blue-400' : 'text-gray-600'}`} />
                <h3 className={`font-semibold ${stage >= 3 ? 'text-white' : 'text-gray-500'}`}>Match Agent</h3>
              </div>
              {getStageStatus(stage, 3) === 'PROCESSING' && <p className="text-sm text-gray-400 italic">Finding alternatives...</p>}
              {getStageStatus(stage, 3) === 'COMPLETED' && matchResult && (
                <div className="mt-3 pt-3 border-t border-white/5">
                  <p className="text-xs text-gray-400">Compatible parts</p>
                  <p className="text-sm text-blue-300 mt-1">→ {matchResult.length} matches found</p>
                </div>
              )}
            </div>

            {/* Stage 4 */}
            <div className={`glass-panel p-5 relative overflow-hidden transition-all duration-500 ${stage >= 4 ? (stage === 4 ? 'border-indigo-500/50 shadow-[0_0_20px_rgba(79,70,229,0.15)]' : 'border-emerald-500/30') : ''} ${stage < 4 ? 'opacity-50' : ''}`}>
              {stage === 4 && chatRevealIndex < 4 && <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500/20"><div className="h-full bg-indigo-500 animate-[progress_1.5s_ease-in-out_infinite]"></div></div>}
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-mono text-gray-500">04</span>
                <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded ${stage === 5 ? 'bg-emerald-500/20 text-emerald-400' : stage >= 4 ? 'bg-indigo-500/20 text-indigo-400' : 'bg-gray-800 text-gray-500'}`}>
                  {stage === 5 ? 'COMPLETED' : stage >= 4 ? 'ACTIVE' : 'PENDING'}
                </span>
              </div>
              <div className="flex items-center gap-2 mb-1">
                <MessageSquare className={`w-4 h-4 ${stage >= 4 ? 'text-purple-400' : 'text-gray-600'}`} />
                <h3 className={`font-semibold ${stage >= 4 ? 'text-white' : 'text-gray-500'}`}>Chase Agent</h3>
              </div>
              {stage === 4 && <p className="text-sm text-gray-400 italic">Negotiating supplies...</p>}
              {stage === 5 && (
                <div className="mt-3 pt-3 border-t border-white/5">
                  <p className="text-xs text-gray-400">Recovery Plan</p>
                  <p className="text-sm text-emerald-400 font-semibold mt-1">→ Plan Ready</p>
                </div>
              )}
            </div>
          </div>

          {/* DYNAMIC CONTENT AREA */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            
            {/* LEFT COLUMN: IMPACT & ALTERNATIVES */}
            <div className="lg:col-span-1 space-y-6">
              {stage >= 2 && impactResult && (
                <div className="glass-panel p-6 animate-[fadeInUp_0.4s_ease-out]">
                  <h3 className="text-lg font-semibold text-white mb-4 border-b border-white/10 pb-2">Business Impact</h3>
                  
                  <div className="space-y-4">
                    <div className="bg-white/5 rounded-lg p-4 border border-white/5">
                      <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Revenue at Risk</p>
                      <p className="text-3xl font-bold text-orange-400">${impactResult.revenueAtRiskPerDay.toLocaleString()} <span className="text-sm text-gray-500 font-normal">/ day</span></p>
                    </div>
                    
                    <div>
                      <p className="text-xs text-gray-400 uppercase tracking-wider mb-2">Affected Products ({impactResult.affectedProducts.length})</p>
                      <div className="flex flex-wrap gap-2">
                        {impactResult.affectedProducts.map(p => (
                          <span key={p} className="px-2 py-1 bg-gray-800 border border-gray-700 rounded text-xs text-gray-300">
                            {p}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {stage >= 3 && matchResult && (
                <div className="glass-panel p-6 animate-[fadeInUp_0.4s_ease-out]">
                  <h3 className="text-lg font-semibold text-white mb-4 border-b border-white/10 pb-2">Compatible Alternatives</h3>
                  <div className="space-y-3">
                    {matchResult.map((alt, i) => (
                      <div key={i} className={`p-3 rounded-lg border ${i === 0 ? 'bg-indigo-900/20 border-indigo-500/30' : 'bg-white/5 border-white/5'}`}>
                        <div className="flex justify-between items-start mb-1">
                          <p className="font-mono text-sm text-white font-bold">{alt.partNumber}</p>
                          {i === 0 && <span className="text-[9px] uppercase tracking-wider bg-indigo-500/20 text-indigo-300 px-1.5 py-0.5 rounded">Top Match</span>}
                        </div>
                        <p className="text-xs text-gray-400">{alt.vendor}</p>
                        <p className="text-xs text-gray-500 mt-2">{alt.note}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            {/* RIGHT COLUMN: NEGOTIATION & RESOLUTION */}
            <div className="lg:col-span-2 space-y-6">
              {stage >= 4 && negotiateResult && (
                <div className="glass-panel flex flex-col h-[400px] animate-[fadeInUp_0.4s_ease-out]">
                  <div className="p-4 border-b border-white/10 flex justify-between items-center bg-white/5 rounded-t-xl">
                    <div>
                      <h3 className="text-lg font-semibold text-white">Chase Agent</h3>
                      <p className="text-xs text-gray-400">Autonomous supplier negotiation</p>
                    </div>
                    {stage === 4 ? (
                      <div className="flex items-center gap-2 px-3 py-1 bg-indigo-500/20 rounded-full border border-indigo-500/30">
                        <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse"></div>
                        <span className="text-xs text-indigo-300 font-medium tracking-wide uppercase">Negotiating</span>
                      </div>
                    ) : (
                      <div className="flex items-center gap-2 px-3 py-1 bg-gray-800 rounded-full border border-gray-700">
                        <span className="text-xs text-gray-400 font-medium tracking-wide uppercase">Session Closed</span>
                      </div>
                    )}
                  </div>
                  
                  <div className="flex-1 overflow-y-auto p-6 space-y-4">
                    {negotiateResult.chatLog.slice(0, chatRevealIndex).map((msg, i) => (
                      <div key={i} className={`flex w-full ${msg.from === 'System' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[80%] rounded-lg p-3 text-sm ${
                          msg.from === 'System' 
                            ? 'bg-indigo-600 text-white rounded-br-none' 
                            : 'bg-gray-800 text-gray-200 border border-gray-700 rounded-bl-none'
                        }`}>
                          <p className="text-[10px] uppercase tracking-wider mb-1 opacity-70 font-semibold">{msg.from === 'System' ? 'Chase Agent' : msg.from}</p>
                          <p>{msg.text}</p>
                        </div>
                      </div>
                    ))}
                    {stage === 4 && chatRevealIndex < negotiateResult.chatLog.length && (
                      <div className="flex justify-start">
                        <div className="bg-gray-800 border border-gray-700 rounded-lg rounded-bl-none p-4 flex gap-1 items-center">
                          <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></div>
                          <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></div>
                          <div className="w-1.5 h-1.5 bg-gray-500 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></div>
                        </div>
                      </div>
                    )}
                    <div ref={chatEndRef} />
                  </div>
                </div>
              )}

              {/* FINAL PLAN */}
              {stage === 5 && negotiateResult && (
                <div className="glass-panel-success p-8 animate-[scaleIn_0.5s_ease-out]">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="w-12 h-12 rounded-full bg-emerald-500/20 flex items-center justify-center border border-emerald-500/50">
                      <CheckCircle className="w-6 h-6 text-emerald-400" />
                    </div>
                    <div>
                      <h2 className="text-2xl font-bold text-white">Recovery Plan Ready</h2>
                      <p className="text-emerald-300/80">AI-ranked response to MCU-2201X disruption</p>
                    </div>
                  </div>

                  <div className="bg-black/20 rounded-lg border border-emerald-500/20 p-5 mb-6">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div>
                        <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Supplier</p>
                        <p className="font-semibold text-white">{negotiateResult.rankedPlan[0].vendor}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Replacement Part</p>
                        <p className="font-mono font-semibold text-white">{negotiateResult.rankedPlan[0].part}</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Quantity</p>
                        <p className="font-semibold text-white">{negotiateResult.rankedPlan[0].quantity.toLocaleString()} units</p>
                      </div>
                      <div>
                        <p className="text-xs text-gray-400 uppercase tracking-wider mb-1">Lead Time</p>
                        <p className="font-semibold text-emerald-400">{negotiateResult.rankedPlan[0].days} days</p>
                      </div>
                    </div>
                    <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center">
                      <p className="text-sm text-gray-400">Score: <span className="text-emerald-400 font-semibold">{negotiateResult.rankedPlan[0].score}</span></p>
                      <p className="text-sm text-gray-400">Risk Reduction: <span className="text-emerald-400 font-semibold">94%</span></p>
                    </div>
                  </div>

                  <div className="flex justify-end gap-4">
                    <button className="px-6 py-3 text-sm font-medium text-gray-300 hover:text-white bg-white/5 hover:bg-white/10 rounded-lg transition-colors border border-white/10">
                      View Details
                    </button>
                    {approved ? (
                      <div className="flex items-center gap-2 px-6 py-3 bg-emerald-600/20 border border-emerald-500/50 text-emerald-400 font-semibold rounded-lg">
                        <CheckCircle className="w-5 h-5" /> SAP Ariba Integration Queued
                      </div>
                    ) : (
                      <button 
                        onClick={() => setApproved(true)}
                        className="bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-3 px-8 rounded-lg shadow-[0_0_15px_rgba(16,185,129,0.4)] transition-all flex items-center gap-2"
                      >
                        <CheckCircle className="w-5 h-5" /> Approve Recovery Plan
                      </button>
                    )}
                  </div>
                </div>
              )}
            </div>
            
          </div>
        </div>
      </main>

      <style jsx global>{`
        @keyframes progress {
          0% { width: 0%; transform: translateX(0); }
          50% { width: 50%; transform: translateX(50%); }
          100% { width: 100%; transform: translateX(100%); }
        }
        @keyframes fadeInUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
      `}</style>
    </div>
  );
}
